using Microsoft.Dynamics365.LocalizationFramework;

/// <summary>
/// service class for ER price list report
/// </summary>
public class AVAERWarehouseArrivalService extends SysOperationServiceBase
{
    public str DefaultExportedFileName = "@NDX:NXAWarehouseArrival";

}

Method.Source:
/// <summary>
/// Generates report by using Electronic reporting framework
/// </summary>
/// <param name = "_contract">The object quotation report contract</param>
public void generateReport(AVAERWarehouseArrivalContract _contract)
{
    ERFormatMappingId formatMappingId;
    ERFormatMappingTable eRFormatMappingTable;
    QueryBuildDataSource qbds = _contract.getQuery().dataSourceNo(1);

    AVAERReportToMemory     reportToMemory;

    select firstonly RecId from eRFormatMappingTable where eRFormatMappingTable.Name == WMSParameters::find().AVAERWarehouseArrivalFormat;
    formatMappingId = eRFormatMappingTable.RecId;
    if (formatMappingId)
    {
        try
        {
            ERIModelDefinitionParamsAction parameters = new ERModelDefinitionParamsUIActionComposite().add(new ERModelDefinitionDatabaseContext().addQuery(qbds.file(), _contract.getQuery()));

            // Call ER to generate the report.
            ERIFormatMappingRun formatMappingRun = ERObjectsFactory::createFormatMappingRunByFormatMappingId(formatMappingId, DefaultExportedFileName);
            formatMappingRun.parmShowPromptDialog(true);
            formatMappingRun.withParameter(parameters);

            AVAWMSArrivalOverviewTmp  locArrivalOverview;

            str             ERreportName; 
            Map             reportMap = new Map(Types::String,Types::Class);
            reportMap.insert('', new System.IO.MemoryStream());

            if (_contract.parmPrintToMemory() == NoYes::Yes)
            {
                Query       locQuery = new Query(_contract.getQuery());
                QueryRun    locQueryRun = new QueryRun(locQuery);
                ERreportName = WMSParameters::find().AVAERWarehouseArrivalFormat;

                while (locQueryRun.next())
                {
                    locArrivalOverview.data(locQueryRun.get(tableNum(AVAWMSArrivalOverviewTmp)));
                }

                delete_from  reportToMemory
                where reportToMemory.refRecId == locArrivalOverview.RecId
                   && reportToMemory.RefTableId == tableNum(AVAWMSArrivalOverviewTmp)
                   && reportToMemory.ReportName == ERreportName;


                reportToMemory.RefRecId   = locArrivalOverview.RecId;
                reportToMemory.RefTableId = tableNum(AVAWMSArrivalOverviewTmp);
                reportToMemory.ReportName = ERreportName;
                reportToMemory.insert();



                ERIFileDestinationFactoryHost factoryHost = ERCast::asObject(formatMappingRun) as ERIFileDestinationFactoryHost;
                if (factoryHost)
                {
                    ERIFileDestinationFactory fileDestinationFactory = factoryHost.getFileDestinationFactory();
                    factoryHost.setFileDestinationFactory(AVAERMemoryDestinationFactory::construct(fileDestinationFactory,reportToMemory ));
                }

                formatMappingRun.parmShowPromptDialog(false);

            }

            formatMappingRun.run();

        }
        catch
        {
            // An error occurred while exporting data.
            error("@SYP4861341");
        }
    }
    else
    {
        // There is no data available.
        info("@SYS300117");
    }
}
